pack.set:
/**
 * Pack: the cold inputs remember, `bang` sends.
 *
 * Max's pack, with names instead of positions — what comes out is an object
 * keyed by the input each value arrived on, so the names drawn on the node are
 * the names whatever is downstream reads.  Add or rename inputs freely; this
 * works for any of them.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {};
if (field === "bang") {
    edges.value = {...node.data};
} else {
    node.data[field] = value;
}

collect.set:
/**
 * Collect: hold values until there are `count` of them, then send them as one.
 *
 * Max's `zl group`, and the reason a fan-in is safe: many connectors into one
 * field arrive one at a time, each running this node again, and nothing
 * downstream should see a half-assembled answer.  `reset` throws away what has
 * been collected so far, for a branch that legitimately did not fire.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {count: 2, items: []};
if (field === "reset") {
    node.data.items = [];
    return;
}
node.data.items = (node.data.items || []).concat([value]);
if (node.data.items.length >= Number(node.data.count || 0)) {
    const all = node.data.items;
    node.data.items = [];
    edges.value = all;
}

trigger.set:
/**
 * Trigger: one in, many out, in an order you can rely on.
 *
 * Max's `trigger` fires its outlets right to left, so that everything a hot
 * inlet depends on has already arrived by the time it fires.  Outputs here are
 * drawn top to bottom, so the last one fires first.  Delete the outputs you do
 * not need; this sends to whichever are there.
 */
const names = ((properties.outputs || []).map((o) => o.name)).reverse();
for (const name of names) {
    edges[name] = value;
}

unpack.set:
/**
 * Unpack: an object in, each key out of the output named for it.
 *
 * Max's `unpack`, by name rather than position: name the outputs after the
 * keys you want.  An array is unpacked by index (0, 1, 2).  Outputs fire last
 * first, for the same reason Trigger does — so nothing downstream sees half
 * of an object.  A key with no output is left alone rather than lost quietly:
 * it goes out `rest` if there is one.
 */
const source = Array.isArray(value)
    ? value.reduce((o, v, i) => { o[String(i)] = v; return o; }, {})
    : (value && typeof value === "object" ? value : {value: value});
const names = ((properties.outputs || []).map((o) => o.name)).reverse();
const rest = {};
Object.keys(source).forEach((key) => { if (names.indexOf(key) === -1) { rest[key] = source[key]; } });
for (const name of names) {
    if (name === "rest") { continue; }
    if (source[name] !== undefined) { edges[name] = source[name]; }
}
if (names.indexOf("rest") !== -1 && Object.keys(rest).length) { edges.rest = rest; }

store.set:
/**
 * Store: `value` remembers, `bang` sends.
 *
 * Max's `v`.  The cold input is how a value waits for the right moment — the
 * difference between a graph that reacts to whatever arrived last and one that
 * decides when to read it.  What is remembered survives between runs, because
 * `node.data` does.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {};
if (field === "value") {
    node.data.held = value;
    return;
}
edges.value = node.data.held;

toggle.set:
/**
 * Toggle: flips on each bang and says which it now is.
 *
 * `set` puts it where you want without sending, so a graph can be armed
 * before it is started.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {on: false};
if (field === "set") {
    node.data.on = !!value;
    return;
}
node.data.on = !node.data.on;
edges.value = node.data.on;

counter.set:
/**
 * Counter: counts what arrives and sends the running count.
 *
 * Max's `counter`.  Useful as an end in itself, and as the thing a graph asks
 * when it wants to know how far round a loop it has gone.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {count: 0};
if (field === "reset") {
    node.data.count = 0;
    return;
}
node.data.count = (node.data.count || 0) + 1;
edges.count = node.data.count;

route.set:
/**
 * Route: one value in, out of the output that its `kind` names.
 *
 * Max's `route`, on a named property rather than a leading symbol: set
 * `node.data.on` to the property to read (`kind` by default), name the outputs
 * after the values you expect, and anything else goes out `unmatched` — which
 * is there so a value nobody expected is visible rather than dropped.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {on: "kind"};
const key = value && typeof value === "object" ? value[node.data.on || "kind"] : value;
const names = (properties.outputs || []).map((o) => o.name);
const name = names.indexOf(String(key)) !== -1 ? String(key) : "unmatched";
if (names.indexOf(name) !== -1) {
    edges[name] = value;
}

gate.set:
/**
 * Gate: values pass while it is open, and are dropped while it is shut.
 *
 * Max's `gate`.  Shut by default, because a gate that passes everything until
 * told otherwise is a gate that does nothing on the run that matters — the
 * first one.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {open: false};
if (field === "open") {
    node.data.open = !!value;
    return;
}
if (node.data.open) {
    edges.value = value;
}

select.set:
/**
 * Select: equal goes out `yes`, everything else out `no`.
 *
 * Max's `select`, with the unmatched case given somewhere to go rather than
 * being dropped.  `match` sets what to compare against without testing, so the
 * thing being matched can be decided by the graph.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {match: ""};
if (field === "match") {
    node.data.match = value;
    return;
}
const same = JSON.stringify(value) === JSON.stringify(node.data.match);
edges[same ? "yes" : "no"] = value;

iterate.set:
/**
 * Iterate: an array in, its elements out one at a time, then `done`.
 *
 * Max's `iter`.  Each element is a delivery of its own, so whatever is
 * downstream runs once per element and the scheduler counts every one against
 * the budget — a loop that cannot run away unnoticed.  `done` fires after the
 * last, carrying how many there were, which is what Collect wants to be told.
 */
const items = Array.isArray(value) ? value : (value === undefined ? [] : [value]);
for (const item of items) {
    edges.each = item;
}
edges.done = items.length;

repeat.set:
/**
 * Repeat: send `times` times, counting, then `done`.
 *
 * Max's `uzi`, bounded rather than free-running: the count is a number you can
 * see on the node, and every send is a hop the execution budget counts, so a
 * loop that is too big is refused rather than discovered later.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {times: 4};
if (field === "times") {
    node.data.times = Number(value) || 0;
    return;
}
const times = Math.max(0, Math.floor(Number(node.data.times) || 0));
for (let i = 0; i < times; i++) {
    edges.each = {index: i, of: times, value: value};
}
edges.done = times;

delay.set:
/**
 * Delay: hold a value for a while, then send it.
 *
 * Max's `delay`/`pipe`.  The wait is awaited rather than left running, so the
 * execution does not end while a value is still in the air — which is what
 * makes "the run has finished" mean something.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {ms: 250};
if (field === "ms") {
    node.data.ms = Number(value) || 0;
    return;
}
const ms = Math.max(0, Number(node.data.ms) || 0);
await new Promise((resolve) => setTimeout(resolve, ms));
host.throwIfCancelled();
edges.value = value;

if.set:
/**
 * If: a condition a person can edit, rather than code they have to open.
 *
 * The test is written on the node (`value > 10`, `value.kind === "bucket"`)
 * and read as data, so a graph can be reasoned about without reading every
 * set script.  A condition that throws sends nothing and says why, rather
 * than quietly choosing a branch.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {test: "value"};
const test = String(node.data.test || "value");
let passed;
try {
    passed = Function("value", "state", "properties", "return (" + test + ");")(value, state, properties);
} catch (err) {
    throw new Error("If: " + test + " — " + err.message);
}
edges[passed ? "then" : "else"] = value;

get.set:
/**
 * Get: read one path out of what arrives.
 *
 * `a.b.0.c`, the way anyone would write it.  A path that is not there goes out
 * `missing` carrying the path, rather than sending undefined down the happy
 * road — a missing value should be a branch, not a surprise later.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {path: ""};
if (field === "path") {
    node.data.path = String(value || "");
    return;
}
const parts = String(node.data.path || "").split(".").filter(Boolean);
let at = value;
for (const part of parts) {
    if (at === null || at === undefined) { at = undefined; break; }
    at = at[part];
}
if (at === undefined) {
    edges.missing = {path: node.data.path, value: value};
} else {
    edges.value = at;
}

format.set:
/**
 * Format: a string from a pattern, with what arrived in it.
 *
 * `${value.name} in ${value.region}` — the pattern is data on the node, so a
 * label, a key or a name can be composed on the canvas instead of in code.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {pattern: "${value}"};
const pattern = String(node.data.pattern || "");
edges.value = pattern.replace(/\$\{([^}]*)\}/g, (whole, expression) => {
    try {
        const read = Function("value", "state", "return (" + expression + ");")(value, state);
        return read === undefined || read === null ? "" : String(read);
    } catch (err) {
        return whole;
    }
});

log.set:
/**
 * Log: see what is passing, without stopping it.
 *
 * Max's `print`, except the place it prints to is the execution's own stream of
 * observations — so what a graph saw is beside what it did, in the same order,
 * wherever it ran.  The value passes through unchanged, so a Log can be left
 * in the middle of a working graph.
 */
node.data = (node.data && typeof node.data === "object") ? node.data : {label: ""};
host.emit("log", {label: node.data.label || node.properties.name, value: value});
edges.value = value;
